import React, { useState } from 'react';
import { mediaAPI } from '../services/api';

function MediaItem({ media, onRate }) {
  const [rating, setRating] = useState('');

  const handleView = async () => {
    try {
      await mediaAPI.view(media._id);
    } catch (error) {
      console.error('Error incrementing view:', error);
    }
  };

  const handleRate = async () => {
    if (!rating) return;
    try {
      await mediaAPI.rate(media._id, parseInt(rating));
      setRating('');
      onRate(); // Refresh the feed
    } catch (error) {
      console.error('Error adding rating:', error);
    }
  };

  const averageRating = media.ratings.length > 0
    ? (media.ratings.reduce((sum, r) => sum + r.value, 0) / media.ratings.length).toFixed(1)
    : 'No ratings';

  return (
    <div className="media-item">
      <h4>{media.title}</h4>
      {media.mediaType === 'image' ? (
        <img
          src={`http://localhost:5000${media.fileUrl}`}
          alt={media.title}
          onClick={handleView}
          style={{ maxWidth: '100%', cursor: 'pointer' }}
        />
      ) : (
        <video
          src={`http://localhost:5000${media.fileUrl}`}
          controls
          onPlay={handleView}
          style={{ maxWidth: '100%' }}
        />
      )}
      <p><strong>Caption:</strong> {media.caption}</p>
      <p><strong>Location:</strong> {media.location}</p>
      <p><strong>People:</strong> {media.people.join(', ')}</p>
      <p><strong>Views:</strong> {media.views}</p>
      <p><strong>Average Rating:</strong> {averageRating}</p>
      <div className="rating-section">
        <select value={rating} onChange={(e) => setRating(e.target.value)}>
          <option value="">Rate (1-5)</option>
          <option value="1">1</option>
          <option value="2">2</option>
          <option value="3">3</option>
          <option value="4">4</option>
          <option value="5">5</option>
        </select>
        <button onClick={handleRate}>Submit Rating</button>
      </div>
    </div>
  );
}

export default MediaItem;
